program = '''from collections import Counter


def transform(grid):
    size = len(grid)
    n = next(k for k in range(1, 31) if k * k + k - 1 == size)
    stride = n + 1
    observed = {}
    patterns = []

    for i in range(n):
        for j in range(n):
            r0, c0 = i * stride, j * stride
            pattern = tuple(
                tuple(int(grid[r0 + r][c0 + c] == 2) for c in range(n))
                for r in range(n)
            )
            if any(any(row) for row in pattern):
                observed[i, j] = pattern
                patterns.append(pattern)

    template = Counter(patterns).most_common(1)[0][0]
    output = [[0] * size for _ in range(size)]
    for i in range(n):
        for j in range(n):
            if not template[i][j]:
                continue
            r0, c0 = i * stride, j * stride
            pattern = observed.get((i, j), template)
            for r in range(n):
                for c in range(n):
                    output[r0 + r][c0 + c] = 2 if pattern[r][c] else 0
            output[r0 + i][c0 + j] = 8
    return output
'''
